import { resolve, join } from "node:path";
import { existsSync, writeFileSync, readFileSync, readdirSync } from "node:fs";
import { execFile } from "node:child_process";
import { promisify } from "node:util";
const exec = promisify(execFile);
export const autoDocsTool = {
    name: "auto_docs",
    description: "Generate documentation from code: README, API docs, architecture overview, and changelog. " +
        "Analyzes the codebase and produces markdown documentation.",
    parameters: {
        type: "object",
        properties: {
            action: {
                type: "string",
                enum: ["readme", "api", "architecture", "changelog", "all"],
                description: "What to generate",
            },
            path: { type: "string", description: "Output directory (default: cwd)" },
        },
        required: ["action"],
    },
    async execute(args, ctx) {
        const cwd = ctx.cwd;
        const action = String(args.action || "readme");
        const outDir = args.path ? resolve(cwd, args.path) : cwd;
        const results = [];
        if (action === "readme" || action === "all") {
            const readme = generateReadme(cwd);
            const outPath = join(outDir, "README.md");
            writeFileSync(outPath, readme, "utf8");
            results.push(`README.md → ${outPath}`);
        }
        if (action === "api" || action === "all") {
            const api = generateApiDocs(cwd);
            const outPath = join(outDir, "API.md");
            writeFileSync(outPath, api, "utf8");
            results.push(`API.md → ${outPath}`);
        }
        if (action === "architecture" || action === "all") {
            const arch = generateArchitecture(cwd);
            const outPath = join(outDir, "ARCHITECTURE.md");
            writeFileSync(outPath, arch, "utf8");
            results.push(`ARCHITECTURE.md → ${outPath}`);
        }
        if (action === "changelog" || action === "all") {
            const changelog = await generateChangelog(cwd);
            const outPath = join(outDir, "CHANGELOG.md");
            writeFileSync(outPath, changelog, "utf8");
            results.push(`CHANGELOG.md → ${outPath}`);
        }
        return `Generated documentation:\n${results.map((r) => `  • ${r}`).join("\n")}`;
    },
};
function generateReadme(cwd) {
    const pkg = existsSync(join(cwd, "package.json")) ? JSON.parse(readFileSync(join(cwd, "package.json"), "utf8")) : null;
    const name = pkg?.name || cwd.split("/").pop() || "project";
    const desc = pkg?.description || "A software project.";
    const scripts = pkg?.scripts || {};
    const lines = [];
    lines.push(`# ${name}`);
    lines.push("");
    lines.push(desc);
    lines.push("");
    // Detect tech stack
    const deps = { ...pkg?.dependencies, ...pkg?.devDependencies };
    const stack = [];
    if (deps?.next)
        stack.push("Next.js");
    if (deps?.react)
        stack.push("React");
    if (deps?.vue)
        stack.push("Vue");
    if (deps?.express)
        stack.push("Express");
    if (deps?.fastify)
        stack.push("Fastify");
    if (deps?.expo)
        stack.push("Expo");
    if (deps?.typescript)
        stack.push("TypeScript");
    if (existsSync(join(cwd, "Cargo.toml")))
        stack.push("Rust");
    if (existsSync(join(cwd, "go.mod")))
        stack.push("Go");
    if (existsSync(join(cwd, "pyproject.toml")))
        stack.push("Python");
    if (stack.length) {
        lines.push(`## Tech Stack`);
        lines.push("");
        lines.push(stack.join(" · "));
        lines.push("");
    }
    // Scripts
    if (Object.keys(scripts).length) {
        lines.push("## Scripts");
        lines.push("");
        lines.push("| Command | Description |");
        lines.push("|---------|-------------|");
        for (const [k, v] of Object.entries(scripts)) {
            lines.push(`| \`npm run ${k}\` | \`${v}\` |`);
        }
        lines.push("");
    }
    // Installation
    lines.push("## Installation");
    lines.push("");
    lines.push("```bash");
    lines.push("npm install");
    lines.push("```");
    lines.push("");
    // Development
    lines.push("## Development");
    lines.push("");
    lines.push("```bash");
    lines.push(scripts.dev ? "npm run dev" : scripts.start ? "npm start" : "npm run build");
    lines.push("```");
    lines.push("");
    lines.push("---");
    lines.push("");
    lines.push("*Generated by Spyro Studio*");
    return lines.join("\n");
}
function generateApiDocs(cwd) {
    const lines = [];
    lines.push("# API Documentation");
    lines.push("");
    lines.push("*Auto-generated from route handlers.*");
    lines.push("");
    // Scan for route files
    const routeDirs = ["src/routes", "src/api", "app/api", "pages/api", "routes"];
    for (const dir of routeDirs) {
        const fullPath = join(cwd, dir);
        if (!existsSync(fullPath))
            continue;
        lines.push(`## ${dir}`);
        lines.push("");
        try {
            const files = readdirSync(fullPath, { recursive: true }).filter((f) => /\.(ts|js)$/.test(f));
            for (const f of files) {
                lines.push(`### ${f}`);
                lines.push("");
                const content = readFileSync(join(fullPath, f), "utf8");
                // Extract route definitions
                const routePatterns = [
                    /app\.(get|post|put|delete|patch)\s*\(\s*["'`]([^"'`]+)["'`]/g,
                    /router\.(get|post|put|delete|patch)\s*\(\s*["'`]([^"'`]+)["'`]/g,
                    /@(Get|Post|Put|Delete|Patch)\s*\(\s*["'`]([^"'`]+)["'`]/g,
                ];
                for (const pat of routePatterns) {
                    let m;
                    while ((m = pat.exec(content)) !== null) {
                        lines.push(`- \`${m[1].toUpperCase()} ${m[2]}\``);
                    }
                }
                lines.push("");
            }
        }
        catch { }
    }
    if (lines.length <= 4) {
        lines.push("No API routes found. Add routes to src/routes/ or app/api/.");
    }
    return lines.join("\n");
}
function generateArchitecture(cwd) {
    const lines = [];
    lines.push("# Architecture Overview");
    lines.push("");
    lines.push("*Auto-generated from project structure.*");
    lines.push("");
    // Scan top-level directories
    try {
        const entries = readdirSync(cwd, { withFileTypes: true });
        const dirs = entries.filter((e) => e.isDirectory() && !e.name.startsWith(".") && e.name !== "node_modules").map((e) => e.name);
        const files = entries.filter((e) => e.isFile()).map((e) => e.name);
        lines.push("## Top-level structure");
        lines.push("");
        lines.push("```");
        for (const d of dirs)
            lines.push(`${d}/`);
        for (const f of files.slice(0, 20))
            lines.push(f);
        lines.push("```");
        lines.push("");
        // Count files by type
        const counts = {};
        function walk(dir, depth) {
            if (depth > 3)
                return;
            try {
                for (const e of readdirSync(dir, { withFileTypes: true })) {
                    if (e.name.startsWith(".") || e.name === "node_modules" || e.name === "dist" || e.name === "build")
                        continue;
                    if (e.isDirectory())
                        walk(join(dir, e.name), depth + 1);
                    else {
                        const ext = e.name.split(".").pop() || "other";
                        counts[ext] = (counts[ext] || 0) + 1;
                    }
                }
            }
            catch { }
        }
        walk(cwd, 0);
        lines.push("## File counts by type");
        lines.push("");
        lines.push("| Extension | Count |");
        lines.push("|-----------|-------|");
        for (const [ext, count] of Object.entries(counts).sort((a, b) => b[1] - a[1]).slice(0, 15)) {
            lines.push(`| .${ext} | ${count} |`);
        }
        lines.push("");
    }
    catch { }
    return lines.join("\n");
}
async function generateChangelog(cwd) {
    const lines = [];
    lines.push("# Changelog");
    lines.push("");
    lines.push("*Auto-generated from git history.*");
    lines.push("");
    try {
        const r = await exec("git", ["log", "--oneline", "--format=%h %s (%an, %ad)", "--date=short", "-50"], { cwd });
        const commits = r.stdout.trim().split("\n").filter(Boolean);
        for (const c of commits) {
            lines.push(`- ${c}`);
        }
    }
    catch {
        lines.push("No git history found.");
    }
    lines.push("");
    lines.push("---");
    lines.push("*Generated by Spyro Studio*");
    return lines.join("\n");
}
